<script setup>
import { computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useEvents } from '@/composables/useEvents'
const route=useRoute(),router=useRouter(),{getRegistrationById,getEventById}=useEvents()
const registration=computed(()=>getRegistrationById(route.params.registrationId)),event=computed(()=>registration.value?getEventById(registration.value.eventId):null)
function printTicket(){window.print()}
function date(v){if(!v)return 'Date to be announced';const d=new Date(v);return Number.isNaN(d.getTime())?v:new Intl.DateTimeFormat('en',{dateStyle:'full',timeStyle:'short'}).format(d)}
</script>
<template><main class="receipt-page"><button class="back" @click="router.push('/your-events')">← Back to Your Events</button><section v-if="registration&&event" class="receipt"><header><span class="check">✓</span><span class="eyebrow">GATHERLY · ADMISSION</span><h1>Your event ticket</h1><p>Show this ticket to the organizer when you arrive.</p></header><div class="ticket-title"><span>{{event.category}}</span><h2>{{event.title}}</h2><p>{{event.desc}}</p></div><div class="ticket-info"><div><small>DATE &amp; TIME</small><strong>{{date(event.date)}}</strong></div><div><small>LOCATION</small><strong>{{event.location}}</strong></div><div><small>ATTENDEE</small><strong>{{registration.attendee.name}}</strong></div><div><small>EMAIL</small><strong>{{registration.attendee.email}}</strong></div><div><small>PHONE</small><strong>{{registration.attendee.phone}}</strong></div><div><small>DATE OF BIRTH</small><strong>{{registration.attendee.dateOfBirth}}</strong></div></div><div class="reason"><small>WHY YOU'RE ATTENDING</small><p>{{registration.attendee.reason}}</p></div><footer><span>Registration reference</span><strong>{{registration.reference}}</strong></footer><button class="print" @click="printTicket">Print ticket</button></section><section v-else class="missing"><span class="check">?</span><h1>Ticket not found</h1><p>This ticket may have been cancelled or is no longer available.</p><RouterLink to="/your-events" class="browse">Go to Your Events</RouterLink></section></main></template>
<style scoped>.receipt-page{max-width:760px;margin:auto;color:#211d47}.back{margin-bottom:1rem;padding:.4rem 0;border:0;color:#77768a;background:transparent;font:inherit;font-size:.8rem;font-weight:700;cursor:pointer}.receipt{overflow:hidden;border:1px solid #e9e7f1;border-radius:22px;background:white;box-shadow:0 14px 44px #251d4710}.receipt header{display:grid;justify-items:center;padding:2rem 1rem 1.5rem;text-align:center;background:linear-gradient(140deg,#faf8ff,#fff7fb)}.check{display:grid;place-items:center;width:48px;height:48px;margin-bottom:.8rem;border-radius:17px;color:#16845b;background:#e7f7ef;font-size:1.3rem;font-weight:800}.eyebrow{color:#9997aa;font-size:.63rem;font-weight:800;letter-spacing:.16em}.receipt header h1{margin:.4rem 0;font-size:1.65rem;letter-spacing:-.04em}.receipt header p,.ticket-title p{margin:0;color:#858397;font-size:.8rem}.ticket-title{padding:1.5rem 1.8rem;border-bottom:1px dashed #e4e1ed}.ticket-title>span{color:#6748ed;font-size:.68rem;font-weight:800}.ticket-title h2{margin:.4rem 0;font-size:1.3rem}.ticket-title p{line-height:1.55}.ticket-info{display:grid;grid-template-columns:1fr 1fr;gap:1.2rem;padding:1.5rem 1.8rem}.ticket-info div{display:grid;gap:.3rem}.ticket-info small,.reason small{color:#9997aa;font-size:.61rem;font-weight:800;letter-spacing:.1em}.ticket-info strong{color:#46445c;font-size:.78rem;overflow-wrap:anywhere}.reason{margin:0 1.8rem;padding:1rem;border-radius:12px;background:#faf9fd}.reason p{margin:.4rem 0 0;color:#69697b;font-size:.78rem;line-height:1.55}.receipt footer{display:flex;justify-content:space-between;gap:1rem;margin:1.4rem 1.8rem;padding:1rem 0;border-top:1px dashed #e4e1ed;color:#858397;font-size:.72rem}.receipt footer strong{color:#6748ed;letter-spacing:.08em}.print{display:block;margin:0 auto 1.5rem;padding:.7rem 1rem;border:0;border-radius:10px;color:#fff;background:#6748ed;font:inherit;font-size:.77rem;font-weight:750;cursor:pointer}.missing{display:grid;justify-items:center;padding:4rem 1rem;text-align:center;border:1px solid #eeedf4;border-radius:18px;background:#fff}.missing .check{color:#6748ed;background:#f0edff}.missing h1{font-size:1.3rem}.missing p{color:#858397;font-size:.8rem}.browse{padding:.7rem .9rem;border-radius:10px;color:#fff;background:#6748ed;text-decoration:none;font-size:.77rem;font-weight:750}@media(max-width:540px){.ticket-info{grid-template-columns:1fr;padding:1.2rem}.ticket-title{padding:1.2rem}.reason{margin:0 1.2rem}.receipt footer{margin:1rem 1.2rem;flex-direction:column}}@media print{.back,.print{display:none}.receipt{box-shadow:none}}</style>
